pub const PICK_READ_NO_DNA: u8 = 7;

pub fn dna_pick(scan: &'static str, detect: &'static str, b: u8) -> u8 {
    if (b >= BOARD_COUNT) {
        return PICK_NO_BOARD;
    }
    let mut n: u32 = cables_matching(scan, b);
    if (n == 0) {
        return PICK_NO_CABLE;
    }
    if (dna_read_allowed(n) == false) {
        return PICK_TWO_CABLES;
    }
    if (idcode_is_row(detect_idcode(detect, pl_pos(b)), b) == false) {
        return PICK_WRONG_DIE;
    }
    return PICK_OK;
}

pub fn reader_first_wrong(out: &'static str, b: u8) -> u8 {
    let mut id: u64 = text_hex_after(out, READER_IDCODE_TAG, 0);
    if (id == HEX_NONE) {
        return PICK_READ_NO_IDCODE;
    }
    if (idcode_is_row(id, b) == false) {
        return PICK_READ_WRONG_DIE;
    }
    if (reader_raw(out, READER_FUSE_TAG) == HEX_NONE) {
        return PICK_READ_NO_DNA;
    }
    if (reader_raw(out, READER_XSC_TAG) == HEX_NONE) {
        return PICK_READ_NO_DNA;
    }
    return PICK_OK;
}

pub fn pick_why(code: u8) -> &'static str {
    if (code == PICK_OK) {
        return "read";
    }
    if (code == PICK_NO_BOARD) {
        return "no such board in bench_boards.t27";
    }
    if (code == PICK_NO_CABLE) {
        return "no cable on the bus matches the board's vid:pid and serial";
    }
    if (code == PICK_TWO_CABLES) {
        return "more than one cable could be the board's; openocd would open whichever it finds first";
    }
    if (code == PICK_WRONG_DIE) {
        return "the die at the board's PL position does not answer its IDCODE";
    }
    if (code == PICK_READ_NO_IDCODE) {
        return "openocd printed no PL_IDCODE read";
    }
    if (code == PICK_READ_WRONG_DIE) {
        return "the PL TAP openocd read is not the board's die";
    }
    return "openocd printed no tagged DNA read";
}

