pub fn decimal_at(text: &'static str, at: u32) -> u32 {
    let mut v: u32 = 0;
    let mut i: u32 = at;
    let mut going: bool = true;
    while going {
        going = false;
        if (i < (text.len() as u32)) {
            let mut c: u32 = (text.as_bytes()[(i) as usize] as u32);
            if (c >= 48) {
                if (c <= 57) {
                    if ((i - at) >= 9) {
                        return NOT_FOUND;
                    }
                    v = ((v * 10) + (c - 48));
                    i = (i + 1);
                    going = true;
                }
            }
        }
    }
    if (i == at) {
        return NOT_FOUND;
    }
    return v;
}

pub fn fasm_chain(fasm: &'static str) -> u32 {
    let mut chain: u32 = NOT_FOUND;
    let mut at: u32 = text_next(fasm, FASM_CHAIN_KEY, 0);
    while (at != NOT_FOUND) {
        let mut n: u32 = decimal_at(fasm, (at + (FASM_CHAIN_KEY.len() as u32)));
        if (n != NOT_FOUND) {
            chain = n;
        }
        at = text_next(fasm, FASM_CHAIN_KEY, (at + 1));
    }
    return chain;
}

pub fn fasm_site_after(fasm: &'static str, above: u32, first: bool) -> u32 {
    let mut best: u32 = NOT_FOUND;
    let mut at: u32 = text_next(fasm, FASM_SITE_KEY, 0);
    while (at != NOT_FOUND) {
        let mut n: u32 = decimal_at(fasm, (at + (FASM_SITE_KEY.len() as u32)));
        if (n != NOT_FOUND) {
            let mut counts: bool = first;
            if (n > above) {
                counts = true;
            }
            if counts {
                if (n < best) {
                    best = n;
                }
            }
        }
        at = text_next(fasm, FASM_SITE_KEY, (at + 1));
    }
    return best;
}

pub fn fasm_site_count(fasm: &'static str) -> u32 {
    let mut n: u32 = 0;
    let mut s: u32 = fasm_site_after(fasm, 0, true);
    while (s != NOT_FOUND) {
        n = (n + 1);
        s = fasm_site_after(fasm, s, false);
    }
    return n;
}

pub fn fasm_site(fasm: &'static str, n: u32) -> u32 {
    let mut s: u32 = fasm_site_after(fasm, 0, true);
    let mut k: u32 = 0;
    while (k < n) {
        s = fasm_site_after(fasm, s, false);
        k = (k + 1);
    }
    return s;
}

