pub fn dna_agreement(fuse_raw: u64, xsc_raw: u64) -> u8 {
    if (fuse_first_wrong(fuse_raw) != DNA_OK) {
        return AGREE_FUSE_BAD;
    }
    if (xsc_first_wrong(xsc_raw) != DNA_OK) {
        return AGREE_XSC_BAD;
    }
    if (dna_from_fuse(fuse_raw) != dna_from_xsc(xsc_raw)) {
        return AGREE_DIFFER;
    }
    return AGREE_SAME_DIE;
}

pub fn dna_all_ones() -> u64 {
    return (pow2(57) - 1);
}

pub fn dna_from_fuse(raw: u64) -> u64 {
    return reverse57((raw / pow2(7)));
}

pub fn dna_from_xsc(raw: u64) -> u64 {
    return reverse57((raw % pow2(57)));
}

pub fn dna_hex_char(dna: u64, k: u32) -> u32 {
    if (k >= DNA_HEX_LEN) {
        return HEX_END;
    }
    let mut nibble: u64 = ((dna / pow2((4 * (((DNA_HEX_LEN - 1) - k) as u64)))) % 16);
    if (nibble < 10) {
        return (48 + (nibble as u32));
    }
    return (87 + (nibble as u32));
}

